"""Migrated Meridian CRM 4.2 opportunity_pipeline workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _field(record: dict, name: str) -> Any:
    """Return a legacy field value, treating missing and None as empty."""
    value = record.get(name, "")
    return "" if value is None else value


def _numeric(value: Any) -> Decimal:
    """Apply legacy empty-string numeric coercion."""
    if value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _has_positive_amount(record: dict) -> bool:
    # NVL(AMT, 0) > 0
    amount = _field(record, "AMT")
    if amount == "":
        amount = 0
    return _numeric(amount) > Decimal("0")


def _has_close_date(record: dict) -> bool:
    # CLOSE_DT <> '00000000'
    return _field(record, "CLOSE_DT") != "00000000"


def _has_lost_reason(record: dict) -> bool:
    # LOST_RSN <> ''
    return _field(record, "LOST_RSN") != ""


_TRANSITIONS = (
    ("P", "qualify", "Q", _has_positive_amount,
     (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
    ("Q", "advance", "N", None,
     (("set", "STAGE_PCT", "60"),)),
    ("N", "close_won", "W", _has_close_date,
     (
         ("set", "STAGE_PCT", "100"),
         ("audit", "OPP_WON"),
         ("notify", "won_deal"),
     )),
    ("P", "close_lost", "L", _has_lost_reason,
     (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    ("Q", "close_lost", "L", _has_lost_reason,
     (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    ("N", "close_lost", "L", _has_lost_reason,
     (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
)


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity-pipeline event using legacy workflow semantics."""
    result_record = dict(record)

    for from_state, transition_event, to_state, guard, actions in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action in actions:
            if action[0] == "set":
                result_record[action[1]] = action[2]
            elif action[0] == "audit":
                audits.append(action[1])
            else:
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
